import { setTimeout as delay } from "node:timers/promises";
import type { Session } from "../browser.ts";
import { CliError } from "../errors.ts";
import { navigate } from "./navigation.ts";
import type { Input } from "./validate.ts";

// Ask Douyin's own assistant, and take its answer as a lead rather than a fact.
//
// The AI search page answers a question in prose and sometimes lists works with
// links. That is useful in a way the feed is not: the feed shows what the platform
// wants to show, while this answers what was asked. But the answer is generated by
// the platform about itself, so it carries the same weight as a search result
// snippet — a pointer to check, never a conclusion to repeat.
//
// The distinction matters for the rest of this tool. Everything else here reports
// what the page literally shows; this reports what a model said about the platform.
// A caller that treats the two as one kind of evidence would quote an AI summary as
// if it had watched the work.

export interface AiAnswer {
	question: string;
	// The answer text, in the order the page rendered it.
	answer: string;
	// Work ids the answer linked to, deduplicated. These are real ids from the page,
	// so they can be opened; the prose around them is not verifiable the same way.
	links: { id: string; text: string }[];
	// Whether the page had finished answering when this was read.
	complete: boolean;
	limits: string;
}

const LIMITS =
	"This is Douyin's assistant answering about its own content, not an observation of any work. Treat the prose as a lead to check by opening the work, and quote it as the platform's claim rather than as something this tool saw. The ids are real page links and can be opened with dy video open.";

export async function askDouyin(session: Session, input: Input, signal: AbortSignal): Promise<AiAnswer> {
	const question = (input.query ?? "").trim();
	if (!question) throw new CliError("invalid_argument", "Ask something: --query <question>");
	if (question.length > 500) throw new CliError("invalid_argument", "Keep the question under 500 characters");
	await navigate(session, "https://www.douyin.com/aisearch?from_nav=1", "agent", signal);
	const prepared = await session.call<{ ready: boolean }>("ai.prepare", { question });
	if (!prepared.ready) throw new CliError("selector_changed", "The AI search box did not appear");
	await session.tab.keyboard.insertText(question);
	await session.tab.keyboard.press("Enter");
	// The answer streams in. Waiting for the text to stop growing is what makes the
	// difference between a partial answer and a complete one, and this reports which.
	const deadline = Date.now() + 45_000;
	let previous = "";
	let stable = 0;
	let answer: AiAnswer | null = null;
	while (Date.now() < deadline) {
		signal.throwIfAborted();
		answer = await session.call<AiAnswer>("ai.answer", { question });
		if (answer.answer === previous && answer.answer.length > 0) stable++;
		else stable = 0;
		previous = answer.answer;
		// Two reads in a row with the same text means the stream finished.
		if (stable >= 2) return { ...answer, complete: true, limits: LIMITS };
		await delay(600, undefined, { signal });
	}
	if (!answer || !answer.answer)
		throw new CliError("timeout", "The AI search page did not answer", {
			hint: "The question may have been refused, or the page changed. Read it with dy page facts.",
		});
	return { ...answer, complete: false, limits: LIMITS };
}
